-- Backend Engineering ("The Fracture") Act 12 -- "Transactions & Concurrency" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), closing Arc II
-- alongside Acts 11 and 13. Same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every world.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be12', 'world-be-12', 'transactions-and-concurrency', '12A - Transactions & Concurrency', 'A citizen is charged twice for the same fee within the same second. Learn what a transaction actually promises before you try to explain how two of them stepped on each other.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be12-1', 'campaign-be12', 'transaction-fundamentals', 'Transaction Fundamentals', 'ACID, transaction boundaries, atomicity failure, isolation levels, lost updates and dirty reads.', 1),
  ('operation-be12-2', 'campaign-be12', 'concurrency-in-practice', 'Concurrency In Practice', 'Non-repeatable reads, phantom reads, locks, deadlocks, optimistic concurrency -- then the double payment itself.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be12-01', 'world-be-12', 'campaign-be12', 'operation-be12-1', 'acid', 'ACID', 'Four letters, four separate promises a database transaction makes -- and each one fails in a different, specific way when it''s missing.', 'advanced', ARRAY['forge'], null, null, '{"type":"simulation","simulationId":"acid-sim"}'::jsonb, '{"xp":190,"credits":35}'::jsonb, false, 1),
  ('mission-be12-02', 'world-be-12', 'campaign-be12', 'operation-be12-1', 'transaction-boundaries', 'Transaction Boundaries', 'BEGIN and COMMIT mark where a transaction actually starts and ends -- everything in between succeeds or fails together.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be12-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"transaction-boundary-sim"}'::jsonb, '{"xp":192,"credits":35}'::jsonb, false, 2),
  ('mission-be12-03', 'world-be-12', 'campaign-be12', 'operation-be12-1', 'atomicity-failure', 'Atomicity Failure', 'Two statements meant to happen together, happening only one at a time, is exactly the failure atomicity exists to prevent.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be12-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"atomicity-failure-sim"}'::jsonb, '{"xp":195,"credits":36}'::jsonb, false, 3),
  ('mission-be12-04', 'world-be-12', 'campaign-be12', 'operation-be12-1', 'isolation-levels', 'Isolation Levels', 'Isolation isn''t one setting -- Postgres offers a spectrum of levels, each trading strictness for concurrency differently.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be12-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"isolation-levels-sim"}'::jsonb, '{"xp":197,"credits":36}'::jsonb, false, 4),
  ('mission-be12-05', 'world-be-12', 'campaign-be12', 'operation-be12-1', 'lost-updates', 'Lost Updates', 'Two transactions both read the same value, both compute a new value from it, and whichever writes last quietly erases the other''s change.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be12-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"lost-update-sim"}'::jsonb, '{"xp":199,"credits":36}'::jsonb, false, 5),
  ('mission-be12-06', 'world-be-12', 'campaign-be12', 'operation-be12-1', 'dirty-reads', 'Dirty Reads', 'Reading a value another transaction hasn''t committed yet -- and might still roll back -- is reading data that may never have actually existed.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be12-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"dirty-read-sim"}'::jsonb, '{"xp":201,"credits":37}'::jsonb, false, 6),
  ('mission-be12-07', 'world-be-12', 'campaign-be12', 'operation-be12-2', 'non-repeatable-reads', 'Non-Repeatable Reads', 'Read the same row twice in one transaction and get two different, both-committed answers -- that''s not a dirty read, it''s something else entirely.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be12-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"non-repeatable-read-sim"}'::jsonb, '{"xp":203,"credits":37}'::jsonb, false, 7),
  ('mission-be12-08', 'world-be-12', 'campaign-be12', 'operation-be12-2', 'phantom-reads-concepts', 'Phantom Reads Concepts', 'Not a row changing value -- a whole new row appearing that matches a query which already ran once.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be12-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"phantom-read-sim"}'::jsonb, '{"xp":205,"credits":37}'::jsonb, false, 8),
  ('mission-be12-09', 'world-be-12', 'campaign-be12', 'operation-be12-2', 'locks', 'Locks', 'A lock is a transaction claiming exclusive rights to a row, or a table, for as long as it needs -- and everyone else waits their turn.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be12-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"locks-sim"}'::jsonb, '{"xp":207,"credits":38}'::jsonb, false, 9),
  ('mission-be12-10', 'world-be-12', 'campaign-be12', 'operation-be12-2', 'deadlocks', 'Deadlocks', 'Two transactions, each holding a lock the other one needs -- neither can proceed, and neither will ever release first on its own.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be12-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"deadlock-sim"}'::jsonb, '{"xp":209,"credits":38}'::jsonb, false, 10),
  ('mission-be12-11', 'world-be-12', 'campaign-be12', 'operation-be12-2', 'optimistic-concurrency', 'Optimistic Concurrency', 'Instead of locking rows up front, check at write time whether anyone else already changed what you read -- and if so, reject and retry.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be12-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"optimistic-concurrency-sim"}'::jsonb, '{"xp":210,"credits":38}'::jsonb, false, 11),
  ('mission-be12-12', 'world-be-12', 'campaign-be12', 'operation-be12-2', 'double-payment', 'Boss: Double Payment', 'A citizen is charged twice for the same service fee within the same second. Two requests, two transactions, and neither one saw the other coming. Everything this Act taught, at once.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be12-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"double-payment-boss-sim"}'::jsonb, '{"xp":470,"credits":105,"badgeIds":["double-payment"],"skillXp":{"databases":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be12-01', 1, 'forge', 'ACID: atomicity, consistency, isolation, durability. Four separate guarantees, bundled into the word "transaction" -- and every one of them fails differently when it''s missing.'),
  ('mission-be12-01', 2, 'forge', 'Atomicity means all-or-nothing. Consistency means constraints hold before and after. Isolation means concurrent transactions don''t see each other''s half-finished work. Durability means once committed, it survives a crash.'),
  ('mission-be12-02', 1, 'mira', 'BEGIN opens a transaction. COMMIT makes every change inside it permanent, all at once. ROLLBACK discards every change inside it, all at once. Nothing in between is visible to anyone else until COMMIT actually happens.'),
  ('mission-be12-02', 2, 'mira', 'Forget to wrap related statements in an explicit transaction, and Postgres treats each one as its own tiny auto-committed transaction -- a crash between two related statements can leave only one of them applied.'),
  ('mission-be12-03', 1, 'forge', 'Atomicity is the all-or-nothing guarantee. If a transfer debits one account and credits another, atomicity says: either both happen, or neither does. There''s no in-between state where only the debit went through.'),
  ('mission-be12-03', 2, 'forge', 'The classic way to break this by accident is running the two statements as separate, un-transacted queries -- so a crash or error between them leaves the system exactly in the state atomicity was supposed to make impossible.'),
  ('mission-be12-04', 1, 'mira', 'Postgres offers four standard isolation levels: Read Uncommitted (treated the same as Read Committed here), Read Committed (the default), Repeatable Read, and Serializable. Each one closes off a different category of anomaly, at a different cost.'),
  ('mission-be12-04', 2, 'mira', 'Stricter isolation means fewer surprises, but more transactions get forced to retry or abort when they conflict. It''s a real tradeoff, not a free upgrade.'),
  ('mission-be12-05', 1, 'forge', 'A lost update happens when two transactions both read the same row, both compute a change based on what they read, and both write back -- and the second write just overwrites the first, as if it never happened.'),
  ('mission-be12-05', 2, 'forge', 'The dangerous part is that neither transaction did anything wrong on its own. The bug only exists in the gap between them.'),
  ('mission-be12-06', 1, 'mira', 'A dirty read is seeing another transaction''s uncommitted changes. If that transaction then rolls back, you acted on data that, as far as the database is concerned, never actually happened.'),
  ('mission-be12-06', 2, 'mira', 'Postgres''s default Read Committed level already prevents dirty reads entirely -- it''s one of the few anomalies Postgres closes off no matter which isolation level you pick.'),
  ('mission-be12-07', 1, 'forge', 'A non-repeatable read is different from a dirty read: both values you see were properly committed. The problem is your own transaction reading the same row twice and getting two different answers.'),
  ('mission-be12-07', 2, 'forge', 'Repeatable Read isolation closes this off -- your transaction locks in one consistent snapshot at the start, and every read within it sees that same snapshot, no matter what commits elsewhere in the meantime.'),
  ('mission-be12-08', 1, 'mira', 'A phantom read isn''t an existing row changing value -- it''s a query''s result set gaining or losing whole rows between two runs, because another transaction inserted or deleted rows matching the same condition in between.'),
  ('mission-be12-08', 2, 'mira', 'Repeatable Read narrows this a lot, but Serializable is what actually closes off phantoms completely.'),
  ('mission-be12-09', 1, 'forge', 'A row-level lock is one transaction saying "nobody else touches this row until I''m done." SELECT ... FOR UPDATE takes exactly that lock explicitly, on the rows it reads.'),
  ('mission-be12-09', 2, 'forge', 'Locks solve races by making one side wait instead of letting both proceed and conflict -- the cost is that waiting, which becomes contention under enough concurrent load.'),
  ('mission-be12-10', 1, 'mira', 'A deadlock is two transactions, each holding a lock the other needs next, each waiting for the other to release first. Neither will, ever, on its own -- there''s no natural way out of that cycle.'),
  ('mission-be12-10', 2, 'mira', 'Postgres detects the cycle itself and forcibly aborts one of the two transactions with a deadlock error, so the other can proceed. The usual fix is acquiring locks on multiple rows in a consistent order every time.'),
  ('mission-be12-11', 1, 'forge', 'Optimistic concurrency skips locking entirely. You read a row along with a version number, do your work, and when you write back you check: is the version still what I read?'),
  ('mission-be12-11', 2, 'forge', 'It costs nothing while transactions don''t actually conflict, and only pays a retry cost when they do -- the opposite tradeoff from locking, which pays upfront every time regardless of whether a conflict would have happened.'),
  ('mission-be12-12', 1, 'mira', 'A citizen was just charged twice for the same service fee -- same amount, less than a second apart. Two separate transactions, both went through.'),
  ('mission-be12-12', 2, 'forge', 'First read: nothing about either request looks malicious. No retry loop, no duplicate submission bug on the client. Two honest transactions, running at almost the same instant.'),
  ('mission-be12-12', 3, 'mira', 'Then find out what actually happened between them. Everything this Act taught, at once.'),
  ('mission-be12-12', 4, 'forge', '...got it. Both transactions read the same "unpaid" balance status before either one wrote back. Neither ever saw the other''s write. Classic lost update -- the second charge just overwrote the first instead of stacking a conflict.'),
  ('mission-be12-12', 5, 'mira', 'Not an attack, not a retry bug. Just two transactions that never had to know about each other, because nothing made them check.'),
  ('mission-be12-12', 6, 'mira', 'Lock the read, or check the version -- either one closes this gap. Make sure it can''t happen again.'),
  ('mission-be12-12', 7, 'forge', 'Transactions solve this. But not everything Forge stores even fits a table -- some of what''s being tracked now is semi-structured, and it doesn''t belong in rows and columns at all.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be12-01-o1', 'mission-be12-01', 1, 'Match the guarantee', 'Match each described failure to the ACID property it violates.'),
  ('mission-be12-02-o1', 'mission-be12-02', 1, 'Find the boundary', 'Identify the line that actually makes the preceding changes permanent.'),
  ('mission-be12-03-o1', 'mission-be12-03', 1, 'Spot the atomicity bug', 'Find the code that can leave a transfer half-completed.'),
  ('mission-be12-04-o1', 'mission-be12-04', 1, 'Order the strictness', 'Order Postgres''s isolation levels from least to most strict.'),
  ('mission-be12-05-o1', 'mission-be12-05', 1, 'Trace the lost update', 'Find the evidence that shows exactly where the update got lost.'),
  ('mission-be12-06-o1', 'mission-be12-06', 1, 'Identify the dirty read', 'Pick the scenario that describes a dirty read specifically.'),
  ('mission-be12-07-o1', 'mission-be12-07', 1, 'Spot the non-repeatable read', 'Identify which evidence shows the same query returning two different committed values within one transaction.'),
  ('mission-be12-08-o1', 'mission-be12-08', 1, 'Identify the phantom', 'Pick the scenario that describes a phantom read specifically.'),
  ('mission-be12-09-o1', 'mission-be12-09', 1, 'Find the explicit lock', 'Identify which line explicitly claims a row lock before the balance is used.'),
  ('mission-be12-10-o1', 'mission-be12-10', 1, 'Diagnose the deadlock', 'Find the evidence that shows the circular wait actually causing the deadlock.'),
  ('mission-be12-11-o1', 'mission-be12-11', 1, 'Spot the version check', 'Identify which line actually detects a conflicting concurrent write.'),
  ('mission-be12-12-o1', 'mission-be12-12', 1, 'Diagnose the read', 'Find the evidence that shows both transactions read the same balance status before either wrote back.'),
  ('mission-be12-12-o2', 'mission-be12-12', 2, 'Name the anomaly', 'Correctly classify what actually happened, not what it looks like on the surface.'),
  ('mission-be12-12-o3', 'mission-be12-12', 3, 'Choose the fix', 'Pick the fix that actually closes this specific gap.'),
  ('mission-be12-12-o4', 'mission-be12-12', 4, 'Close the incident', 'Having found the cause, named the anomaly, and chosen the fix, close the incident.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be12-01-o1-c1', 'mission-be12-01-o1', 1, 'drag_and_drop', 'Match each described failure to the ACID property it violates.', '{"items":[{"id":"i1","text":"A transfer debits one account but the matching credit never happens because the process crashed halfway"},{"id":"i2","text":"A transaction sees another transaction''s uncommitted, half-written balance"},{"id":"i3","text":"A committed payment vanishes after a server restart"},{"id":"i4","text":"A CHECK constraint requiring balance >= 0 is somehow violated after a transaction commits"}],"targets":[{"id":"t1","label":"Atomicity"},{"id":"t2","label":"Isolation"},{"id":"t3","label":"Durability"},{"id":"t4","label":"Consistency"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t3","i4":"t4"}}'::jsonb),

  ('mission-be12-02-o1-c1', 'mission-be12-02-o1', 1, 'code_debugging', 'Which line actually makes both balance changes permanent and visible to other transactions?', '{"language":"sql","code":"BEGIN;\nUPDATE accounts SET balance = balance - 50 WHERE id = 1;\nUPDATE accounts SET balance = balance + 50 WHERE id = 2;\nCOMMIT;","question":"Which line actually makes both balance changes permanent and visible to other transactions?"}'::jsonb, '{"requiredLineIds":["COMMIT;"]}'::jsonb),

  ('mission-be12-03-o1-c1', 'mission-be12-03-o1', 1, 'code_debugging', 'Which line, if the process crashes right after it runs, leaves the transfer atomicity is supposed to prevent?', '{"language":"typescript","code":"await db.query(''''UPDATE accounts SET balance = balance - 50 WHERE id = 1'''');\n// service crashes here\nawait db.query(''''UPDATE accounts SET balance = balance + 50 WHERE id = 2'''');","question":"Which line, if the process crashes right after it runs, leaves the transfer atomicity is supposed to prevent?"}'::jsonb, '{"requiredLineIds":["await db.query(''''UPDATE accounts SET balance = balance - 50 WHERE id = 1'''');"]}'::jsonb),

  ('mission-be12-04-o1-c1', 'mission-be12-04-o1', 1, 'interactive_diagram', 'Order Postgres''s isolation levels from least to most strict.', '{"diagramId":"isolation-level-spectrum","hotspots":[{"id":"read_committed","label":"Read Committed","explanation":"The default -- each statement sees a fresh snapshot of committed data, but the same transaction can see different data on different statements."},{"id":"repeatable_read","label":"Repeatable Read","explanation":"The whole transaction sees one consistent snapshot from its start -- no non-repeatable reads within it."},{"id":"serializable","label":"Serializable","explanation":"The strictest level -- transactions behave as if run one at a time, in some serial order, even though they actually run concurrently."}],"task":"Order Postgres''s isolation levels from least to most strict."}'::jsonb, '{"correctOrderIds":["read_committed","repeatable_read","serializable"]}'::jsonb),

  ('mission-be12-05-o1-c1', 'mission-be12-05-o1', 1, 'investigation', 'Which evidence shows both transactions read the same stale value before either one wrote back?', '{"evidence":[{"id":"ev1","label":"Transaction A","detail":"Reads balance = 100 at 10:00:00.100, computes new balance = 100 - 30 = 70, writes 70 at 10:00:00.400"},{"id":"ev2","label":"Transaction B","detail":"Reads balance = 100 at 10:00:00.150, computes new balance = 100 - 20 = 80, writes 80 at 10:00:00.300"},{"id":"ev3","label":"Final balance","detail":"balance = 70 -- Transaction B''s deduction is nowhere reflected"}],"question":"Which evidence shows both transactions read the same stale value before either one wrote back?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2"]}'::jsonb),

  ('mission-be12-06-o1-c1', 'mission-be12-06-o1', 1, 'multiple_choice', 'Which scenario describes a dirty read, specifically?', '{"question":"Which scenario describes a dirty read, specifically?","options":[{"id":"a","text":"Transaction A reads a row twice and gets two different committed values both times"},{"id":"b","text":"Transaction A reads Transaction B''s uncommitted balance change, and then B rolls back"},{"id":"c","text":"Transaction A can''t find a row it expected because another transaction deleted and committed it first"},{"id":"d","text":"Transaction A waits for a lock held by Transaction B"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be12-07-o1-c1', 'mission-be12-07-o1', 1, 'investigation', 'Which two pieces of evidence together show the same read, inside the same transaction, returning two different committed values?', '{"evidence":[{"id":"ev1","label":"Transaction A, first read","detail":"SELECT balance FROM accounts WHERE id = 1 at 10:00:00 -- returns 100"},{"id":"ev2","label":"Transaction B","detail":"UPDATE accounts SET balance = 60 WHERE id = 1; COMMIT; at 10:00:05"},{"id":"ev3","label":"Transaction A, second read","detail":"SELECT balance FROM accounts WHERE id = 1 at 10:00:10, same transaction as the first read -- returns 60"}],"question":"Which two pieces of evidence together show the same read, inside the same transaction, returning two different committed values?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev3"]}'::jsonb),

  ('mission-be12-08-o1-c1', 'mission-be12-08-o1', 1, 'multiple_choice', 'Which scenario describes a phantom read, specifically?', '{"question":"Which scenario describes a phantom read, specifically?","options":[{"id":"a","text":"A transaction re-reads one specific row and its balance column has changed"},{"id":"b","text":"A transaction runs WHERE status = ''pending'' twice, and the second run includes a new row inserted and committed by someone else in between"},{"id":"c","text":"A transaction reads uncommitted data from another transaction"},{"id":"d","text":"A transaction waits indefinitely for a lock"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be12-09-o1-c1', 'mission-be12-09-o1', 1, 'code_debugging', 'Which line explicitly claims a row lock, forcing any concurrent transaction touching the same row to wait?', '{"language":"sql","code":"BEGIN;\nSELECT balance FROM accounts WHERE id = 1 FOR UPDATE;\nUPDATE accounts SET balance = balance - 50 WHERE id = 1;\nCOMMIT;","question":"Which line explicitly claims a row lock, forcing any concurrent transaction touching the same row to wait?"}'::jsonb, '{"requiredLineIds":["SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;"]}'::jsonb),

  ('mission-be12-10-o1-c1', 'mission-be12-10-o1', 1, 'investigation', 'Which two pieces of evidence together show the actual circular wait that causes the deadlock?', '{"evidence":[{"id":"ev1","label":"Transaction A","detail":"Locks account 1, then tries to lock account 2 -- and waits"},{"id":"ev2","label":"Transaction B","detail":"Locks account 2, then tries to lock account 1 -- and waits"},{"id":"ev3","label":"Error log","detail":"Postgres error: deadlock detected, process X was aborted"}],"question":"Which two pieces of evidence together show the actual circular wait that causes the deadlock?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2"]}'::jsonb),

  ('mission-be12-11-o1-c1', 'mission-be12-11-o1', 1, 'code_debugging', 'Which line actually detects whether another transaction already changed this row since it was read?', '{"language":"sql","code":"UPDATE accounts\nSET balance = 70, version = version + 1\nWHERE id = 1 AND version = 4;","question":"Which line actually detects whether another transaction already changed this row since it was read?"}'::jsonb, '{"requiredLineIds":["WHERE id = 1 AND version = 4;"]}'::jsonb),

  ('mission-be12-12-o1-c1', 'mission-be12-12-o1', 1, 'investigation', 'Which evidence shows the actual root cause -- both transactions reading the same stale status before either wrote back?', '{"evidence":[{"id":"ev1","label":"Transaction A log","detail":"Reads balance_status = unpaid at 14:02:03.100; charges card; writes balance_status = paid at 14:02:03.900"},{"id":"ev2","label":"Transaction B log","detail":"Reads balance_status = unpaid at 14:02:03.250; charges card; writes balance_status = paid at 14:02:03.700"},{"id":"ev3","label":"Payment gateway log","detail":"Two separate successful charges recorded, 550ms apart, both approved"}],"question":"Which evidence shows the actual root cause -- both transactions reading the same stale status before either wrote back?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2"]}'::jsonb),
  ('mission-be12-12-o2-c1', 'mission-be12-12-o2', 1, 'multiple_choice', 'Given both transactions read balance_status = unpaid before either wrote back, what actually happened here?', '{"question":"Given both transactions read balance_status = unpaid before either wrote back, what actually happened here?","options":[{"id":"a","text":"A retry bug -- the client submitted the same request twice"},{"id":"b","text":"A lost update -- both transactions read the same pre-write state and neither saw the other''s change before committing"},{"id":"c","text":"An attack -- someone deliberately sent duplicate requests"},{"id":"d","text":"A network issue duplicating one request into two"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be12-12-o3-c1', 'mission-be12-12-o3', 1, 'multiple_choice', 'Which fix actually prevents this specific lost update from happening again?', '{"question":"Which fix actually prevents this specific lost update from happening again?","options":[{"id":"a","text":"Add a retry limit on the client"},{"id":"b","text":"SELECT the balance status with FOR UPDATE (or use an optimistic version check), so the second transaction can''t write from a stale read it never should have trusted"},{"id":"c","text":"Increase the payment gateway''s timeout"},{"id":"d","text":"Log the transaction twice for audit purposes"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be12-12-o4-c1', 'mission-be12-12-o4', 1, 'boss_encounter', 'Close the incident: state what actually caused the double payment and why the chosen fix closes that specific gap.', '{"stages":[{"objectiveRef":"mission-be12-12-o1","label":"Diagnose the read"},{"objectiveRef":"mission-be12-12-o2","label":"Name the anomaly"},{"objectiveRef":"mission-be12-12-o3","label":"Choose the fix"}],"task":"Close the incident: two transactions both read the same unpaid balance status before either wrote back -- a lost update, not a retry bug and not an attack. Locking the read (or checking a version) closes that specific gap."}'::jsonb, '{"requiredObjectiveIds":["mission-be12-12-o1","mission-be12-12-o2","mission-be12-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be12-01-o1-c1', 'orientation', 'Match each failure to the one guarantee it most directly breaks, not the whole acronym at once.', 10, 1),
  ('mission-be12-01-o1-c1', 'solution', 'i1 breaks atomicity (half-finished), i2 breaks isolation (visible half-state), i3 breaks durability (committed work lost), i4 breaks consistency (a constraint no longer holds).', 20, 2),

  ('mission-be12-02-o1-c1', 'orientation', 'Nothing before this line is visible outside the transaction yet -- both statements are still just pending.', 10, 1),
  ('mission-be12-02-o1-c1', 'solution', 'COMMIT; is the boundary -- everything since BEGIN becomes permanent and visible to other transactions at once.', 20, 2),

  ('mission-be12-03-o1-c1', 'orientation', 'Neither statement is wrapped in BEGIN/COMMIT -- each one commits on its own the moment it runs.', 10, 1),
  ('mission-be12-03-o1-c1', 'solution', 'The first UPDATE commits by itself the instant it runs; a crash right after it leaves the debit applied with no matching credit -- exactly what atomicity is supposed to prevent.', 20, 2),

  ('mission-be12-04-o1-c1', 'orientation', 'Each stricter level closes off one more category of anomaly than the one before it.', 10, 1),
  ('mission-be12-04-o1-c1', 'concept', 'Read Committed still lets the same transaction see different data on different statements; Repeatable Read fixes that but not phantoms; Serializable closes off both.', 20, 2),
  ('mission-be12-04-o1-c1', 'solution', 'Read Committed, then Repeatable Read, then Serializable -- each step closes another category of concurrency anomaly.', 30, 3),

  ('mission-be12-05-o1-c1', 'orientation', 'Compare the timestamps each transaction read at, against when each one wrote.', 10, 1),
  ('mission-be12-05-o1-c1', 'solution', 'ev1 and ev2 -- both transactions read balance = 100 before either had written anything back, so each computed its new value from data the other was about to overwrite.', 20, 2),

  ('mission-be12-06-o1-c1', 'orientation', '"Dirty" specifically means uncommitted, not yet permanent, and possibly about to disappear.', 10, 1),
  ('mission-be12-06-o1-c1', 'solution', 'Reading data that''s still uncommitted -- and that vanishes if the writer rolls back -- is exactly what makes it a dirty read.', 20, 2),

  ('mission-be12-07-o1-c1', 'orientation', 'Look for the same query, in the same transaction, at two different times.', 10, 1),
  ('mission-be12-07-o1-c1', 'solution', 'ev1 and ev3 are the same SELECT in the same transaction, returning 100 and then 60 -- both real, committed values, just not the same one.', 20, 2),

  ('mission-be12-08-o1-c1', 'orientation', 'The row count changing, not one row''s value changing, is the tell here.', 10, 1),
  ('mission-be12-08-o1-c1', 'solution', 'A new row matching the same WHERE condition appearing between two runs of the same query is what defines a phantom read.', 20, 2),

  ('mission-be12-09-o1-c1', 'orientation', 'One specific clause turns an ordinary SELECT into a locking read.', 10, 1),
  ('mission-be12-09-o1-c1', 'solution', 'FOR UPDATE is what turns the SELECT into a locking read -- any other transaction wanting to update this same row now has to wait for this one to finish.', 20, 2),

  ('mission-be12-10-o1-c1', 'orientation', 'A deadlock needs each side to be holding what the other side is waiting for.', 10, 1),
  ('mission-be12-10-o1-c1', 'solution', 'ev1 and ev2 -- A holds account 1 and wants account 2, B holds account 2 and wants account 1, so each blocks the other forever.', 20, 2),

  ('mission-be12-11-o1-c1', 'orientation', 'The WHERE clause here is doing more than just identifying the row.', 10, 1),
  ('mission-be12-11-o1-c1', 'solution', 'WHERE id = 1 AND version = 4 fails to match, and updates zero rows, if anyone else already bumped the version -- that mismatch is the conflict detection.', 20, 2),

  ('mission-be12-12-o1-c1', 'orientation', 'Look for two reads of the same status happening before either transaction had written anything back.', 10, 1),
  ('mission-be12-12-o1-c1', 'solution', 'ev1 and ev2 -- both transactions read balance_status = unpaid before either one committed a write, so neither ever saw the other''s change coming.', 20, 2),
  ('mission-be12-12-o2-c1', 'orientation', 'Rule out anything that requires malicious intent or a client-side bug -- neither is present here.', 10, 1),
  ('mission-be12-12-o2-c1', 'solution', 'Two transactions reading the same pre-write state and each writing back without seeing the other''s change is the textbook definition of a lost update.', 20, 2),
  ('mission-be12-12-o3-c1', 'orientation', 'The fix needs to stop a transaction from writing based on a read it can no longer trust.', 10, 1),
  ('mission-be12-12-o3-c1', 'solution', 'FOR UPDATE (or a version check) closes the gap by making the second transaction either wait for the first, or fail and retry, instead of blindly overwriting it.', 20, 2),
  ('mission-be12-12-o4-c1', 'orientation', 'State the cause, the correct classification, and the fix together -- not just one of the three.', 15, 1),
  ('mission-be12-12-o4-c1', 'solution', 'Both transactions read the same unpaid balance status before either wrote back -- a lost update, not a retry bug or an attack -- and locking the read (or checking a version) is what actually closes that gap.', 25, 2);
